// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address user;

    function setUp() public { 
        c = new C(address(this));
        user = address(0x1234);
        vm.deal(user, 100 ether);
    }

    function testFuzz_property(uint256 depositAmount, uint256 withdrawAmount) public {
        // Bound deposit to reasonable values
        depositAmount = bound(depositAmount, 1.5 ether, 10 ether);
        withdrawAmount = bound(withdrawAmount, 0, 10 ether);

        // Deposit from user
        vm.prank(user);
        c.Deposit{value: depositAmount}();

        // Track initial state
        uint256 initialBalance = c.balances(user);

        // Call CashOut
        vm.prank(user);
        (bool success, ) = address(c).call{gas: 100000}(abi.encodeWithSignature("CashOut(uint256)", withdrawAmount));

        // Get final balance
        uint256 finalBalance = c.balances(user);

        // General rule: after CashOut, user's balance should be initial - withdrawAmount (if successful and withdrawAmount <= initial)
        // Or unchanged if withdrawAmount > initial or call failed
        // The bug makes balance increase instead of decrease
        if (success && withdrawAmount <= initialBalance) {
            assertTrue(finalBalance <= initialBalance, "Balance should not increase on CashOut");
        }
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 amount, uint256 depositAmount) public {
        // Ensure deposit amount is at least MinDeposit to allow deposit
        vm.assume(depositAmount >= 1 ether && depositAmount <= address(this).balance);
        // Ensure amount to cash out is <= caller's balance after deposit
        vm.assume(amount <= depositAmount);

        // Give the contract some ETH for deposit
        vm.deal(address(this), 10 ether);

        // Get caller's balance before CashOut
        uint256 balanceBefore = c.balances(address(this));

        // Deposit first
        (bool depOk,) = address(c).call{value: depositAmount}(abi.encodeWithSignature("Deposit()"));
        require(depOk);

        // Call CashOut
        (bool cashOutOk,) = address(c).call(abi.encodeWithSignature("CashOut(uint256)", amount));

        // If CashOut reverted, no state change; rule trivially holds
        if (!cashOutOk) {
            assertTrue(true);
        } else {
            // After successful CashOut, caller's balance must not increase
            uint256 balanceAfter = c.balances(address(this));
            assertTrue(balanceAfter <= balanceBefore + depositAmount);
        }
    }
}

