pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(address caller, uint256 amt) public {
        vm.assume(amt <= type(uint256).max / 2); // avoid overflow
        vm.assume(caller != address(0));

        // Fund the caller in the contract so he can withdraw
        vm.deal(address(c), 10 ether);
        vm.deal(caller, 10 ether);

        // Make a deposit to ensure caller has a balance
        vm.prank(caller);
        c.Deposit{value: 1 ether}();

        uint256 balanceBefore = c.balances(caller);
        vm.assume(amt <= balanceBefore);

        // Invoke CashOut
        (bool success,) = address(c).call(abi.encodeWithSignature("CashOut(uint256)", amt));
        if (success) {
            uint256 balanceAfter = c.balances(caller);
            // The rule: after a successful CashOut, balance decreases by exactly amt
            assertTrue(balanceAfter + amt == balanceBefore, "Balance increased after CashOut");
        } else {
            // If it reverts, we accept it
            assertTrue(true);
        }
    }
}

