pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(address sender, uint256 depositAmount, uint256 cashOutAmount) public {
        // Bound depositAmount to avoid overflow and ensure it's valid
        vm.assume(depositAmount >= 0 && depositAmount <= type(uint256).max - 1 ether);
        vm.assume(cashOutAmount >= 0 && cashOutAmount <= type(uint256).max);

        // Fund sender with ether
        vm.deal(sender, 100 ether);

        // Optional: make a deposit from sender to increase balances
        vm.prank(sender);
        c.Deposit{value: depositAmount}();

        // Compute total balances before CashOut
        // We can only read balances via public getter; we need a way to sum all.
        // Since we cannot iterate over all addresses, we track the specific sender's balance.
        // The rule must be simpler: for any single address, its balance after CashOut <= before.
        uint256 balanceBefore = c.balances(sender);

        // Call CashOut from sender
        vm.prank(sender);
        (bool success, ) = address(c).call{value: 0}(abi.encodeWithSignature("CashOut(uint256)", cashOutAmount));

        // Read balance after
        uint256 balanceAfter = c.balances(sender);

        // General rule: balance after CashOut should never exceed balance before
        assertTrue(balanceAfter <= balanceBefore);
    }
}

