pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(address caller, uint256 depositAmount, uint256 withdrawAmount) public {
        // Bound depositAmount to avoid overflow and make it either >= or < MinDeposit (1 ether)
        depositAmount = bound(depositAmount, 0, 10 ether);
        // Bound withdrawAmount to be reasonable
        withdrawAmount = bound(withdrawAmount, 0, 10 ether);

        // Ensure caller has enough ether to deposit
        vm.deal(caller, 10 ether);

        // Deposit some amount
        vm.prank(caller);
        c.Deposit{value: depositAmount}();

        // Record total balance in contract (sum of all balances) before CashOut
        // We'll read the caller's balance as a proxy for the only possible balance
        uint256 totalBalanceBefore = c.balances(caller);
        uint256 contractEthBefore = address(c).balance;

        // Execute CashOut
        vm.prank(caller);
        (bool success, ) = address(c).call(abi.encodeWithSelector(c.CashOut.selector, withdrawAmount));

        if (success) {
            // After successful CashOut, the caller's balance should decrease by withdrawAmount
            // and contract eth balance should decrease by withdrawAmount
            uint256 totalBalanceAfter = c.balances(caller);
            uint256 contractEthAfter = address(c).balance;

            // The sum of (totalBalance + contractEth) should decrease by exactly withdrawAmount
            // Because the ether is sent to the caller
            assertTrue(
                (totalBalanceBefore + contractEthBefore) == (totalBalanceAfter + contractEthAfter + withdrawAmount),
                "Total value invariant violated"
            );
        } else {
            // If it reverts, balances should be unchanged
            uint256 totalBalanceAfter = c.balances(caller);
            uint256 contractEthAfter = address(c).balance;
            assertTrue(
                totalBalanceAfter == totalBalanceBefore && contractEthAfter == contractEthBefore,
                "Balance unchanged on revert"
            );
        }
    }
}

