        depositAmount = bound(depositAmount, 0, 1_000_000 ether);
        minDeposit = bound(minDeposit, 0, 1_000_000 ether);
        // Set MinDeposit via a helper — no setter, so we assume it's already set in constructor
        // But the reference has MinDeposit = 1 ether, so we adjust the test to use that value.
        // Actually, we can't change MinDeposit. So we directly use 1 ether as the threshold.
