pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    uint256 constant INITIAL_MIN_DEPOSIT = 1 ether;

    function setUp() public { 
        c = new C(address(this)); 
    }

    function testFuzz_property(uint256 depositAmount, uint256 withdrawAmount) public {
        // Restrict deposit to be above 1 ether so it actually deposits (reference requires this)
        vm.assume(depositAmount > INITIAL_MIN_DEPOSIT);
        // Ensure withdraw amount does not exceed balance (simple boundary)
        vm.assume(withdrawAmount <= depositAmount);

        // Fund the test contract to send ether
        vm.deal(address(this), depositAmount);

        // Perform deposit
        (bool depositOk, ) = address(c).call{value: depositAmount}(""); // use receive() to fund contract first
        // Then call Deposit via c.Deposit{value: depositAmount}() but note c.Deposit is payable
        // Actually better: call c.Deposit{value: depositAmount}()
        c.Deposit{value: depositAmount}();

        // Now withdraw
        (bool cashOutSuccess, ) = address(c).call(
            abi.encodeWithSignature("CashOut(uint256)", withdrawAmount)
        );

        // Only check if CashOut succeeded (otherwise no state change)
        if (cashOutSuccess) {
            // General rule: after any successful CashOut, MinDeposit must equal INITIAL_MIN_DEPOSIT
            assertTrue(c.MinDeposit() == INITIAL_MIN_DEPOSIT, "MinDeposit unchanged after successful CashOut");
        }
    }
}

