pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(address caller, uint256 depositAmount, uint256 cashOutAmount) public {
        vm.assume(caller != address(0));
        vm.assume(caller != address(c));
        vm.assume(depositAmount > 0);
        vm.assume(cashOutAmount > 0);

        // Initial balance of contract
        uint256 initialBalance = address(c).balance;

        // Perform deposit
        vm.deal(caller, depositAmount);
        vm.prank(caller);
        c.Deposit{value: depositAmount}();

        // Perform cash out (may revert)
        vm.prank(caller);
        (bool cashOutSuccess, ) = address(c).call{gas: 100000}(abi.encodeWithSignature("CashOut(uint256)", cashOutAmount));

        // The rule: after the sequence, the contract balance should not exceed the amount that would have been deposited
        // if the deposit condition were changed (i.e., a deposit >= MinDeposit is always accepted)
        // For the reference, deposit only happens if msg.value > MinDeposit,
        // so we can only guarantee the balance is <= total deposited when deposit was > MinDeposit
        // A simple invariant: balance never exceeds depositAmount if deposit was made

        // Actually, we can check: after deposit and potential CashOut, the contract balance should be at most depositAmount
        // But this might fail if CashOut reverts. So we use a bounded property:
        // The contract balance before any operation is 0, after deposit and cashOut, balance <= depositAmount (since we cannot withdraw more)

        uint256 finalBalance = address(c).balance;
        assertTrue(finalBalance <= depositAmount, "Balance exceeded deposit");
    }
}

