contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    // Fuzz parameters: caller address, amount to deposit, amount to cash out
    function testFuzz_property(address caller, uint256 depositAmount, uint256 cashOutAmount) public {
        // Ensure caller is not the zero address (to avoid issues)
        vm.assume(caller != address(0));

        // Restrict depositAmount to a reasonable range (0 to 100 ether)
        depositAmount = bound(depositAmount, 0, 100 ether);

        // Restrict cashOutAmount to a reasonable range
        cashOutAmount = bound(cashOutAmount, 0, 100 ether);

        // Fund the caller with enough ether for deposit
        vm.deal(caller, depositAmount);

        // Deposit if amount is greater than MinDeposit (1 ether)
        vm.prank(caller);
        if (depositAmount > c.MinDeposit()) {
            c.Deposit{value: depositAmount}();
        }

        // Record the caller's balance before CashOut
        uint256 balanceBefore = c.balances(caller);

        // Attempt CashOut
        vm.prank(caller);
        (bool success, ) = address(c).call(abi.encodeWithSelector(c.CashOut.selector, cashOutAmount));

        // Check the rule: if the internal call fails (i.e., success is false), the balance must not change
        if (!success) {
            // The revert condition: CashOut reverted, so balance must be unchanged
            assertTrue(c.balances(caller) == balanceBefore, "Balance should not change when CashOut reverts");
        } else {
            // If CashOut succeeded, the balance should be reduced by cashOutAmount (if it was <= balanceBefore)
            if (cashOutAmount <= balanceBefore) {
                assertTrue(c.balances(caller) == balanceBefore - cashOutAmount, "Balance should decrease by cashOutAmount on success");
            } else {
                // If cashOutAmount > balanceBefore, CashOut should revert (but we already handled failure)
                // Actually, if cashOutAmount > balanceBefore, CashOut should revert, so we should never get here
                // But just in case, we can assert that this branch is unreachable
                assertTrue(false, "Should not reach here if cashOutAmount > balanceBefore");
            }
        }
    }
}

